 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            # Color the hollow center and project the opening leftward from above it.
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            if r0 > 0:
                gaps = [x for x in range(c0+1, c1) if grid[r0][x] == 0]
                if gaps:
                    xgap = gaps[0]
                    for x in range(0, xgap+1):
                        if grid[r0-1][x] == 0:
                            out[r0-1][x] = 2
                    out[r0][xgap] = 2
    return out
